import React, { useState } from 'react';
import {
  Mail,
  Phone,
  MapPin,
  Send,
  CheckCircle2,
  AlertCircle,
  FileText,
  MessageCircle,
} from 'lucide-react';
import { STUDIO_CONTACT } from '../config';
import { PRICING_POLICY_NOTE } from '../data/servicesData';
import { TRANSLATIONS } from '../data/translations';
import { Language } from '../types';
import { validateContactPayload } from '../utils/contactValidator';
import { resolveContactEndpoint } from '../utils/contactDelivery';

const contactEndpoint = resolveContactEndpoint(import.meta.env?.VITE_CONTACT_ENDPOINT, import.meta.env?.DEV);

interface ContactViewProps {
  language: Language;
  onNavigate?: (view: string) => void;
}

const mapServiceToOffer = (service: string) => {
  const lower = service.toLowerCase();
  if (lower.includes('event')) return 'event';
  if (lower.includes('recurring') || lower.includes('ongoing') || lower.includes('löpande'))
    return 'ongoing';
  if (
    lower.includes('digital') ||
    lower.includes('web') ||
    lower.includes('design') ||
    lower.includes('logo')
  )
    return 'digital';
  if (lower.includes('film') || lower.includes('video')) return 'production';
  return 'general';
};

export const ContactView: React.FC<ContactViewProps> = ({ language, onNavigate }) => {
  const t = TRANSLATIONS[language];
  const isSv = language === 'sv';

  const [status, setStatus] = useState<'idle' | 'submitting' | 'success' | 'error' | 'email-ready'>('idle');
  const [serverMessage, setServerMessage] = useState<string>('');
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});

  const [formData, setFormData] = useState({
    name: '',
    company: '',
    email: '',
    phone: '',
    service: 'Event Photography & Highlight Film',
    eventDate: '',
    location: 'Stockholm',
    budget: 'not-sure',
    message: '',
    gdprConsent: false,
    website: '', // Honeypot field — must stay empty
  });

  const mailtoSubject = encodeURIComponent(
    isSv
      ? `Förfrågan: ${formData.service} — ${formData.company || formData.name || 'Dino Studio'}`
      : `Enquiry: ${formData.service} — ${formData.company || formData.name || 'Dino Studio'}`
  );
  const mailtoBody = encodeURIComponent(
    [
      `${isSv ? 'Namn' : 'Name'}: ${formData.name}`,
      `${isSv ? 'Företag / Organisation' : 'Company / Organisation'}: ${formData.company}`,
      `${isSv ? 'E-post' : 'Email'}: ${formData.email}`,
      `${isSv ? 'Telefon' : 'Phone'}: ${formData.phone || '-'}`,
      `${isSv ? 'Tjänst' : 'Service'}: ${formData.service}`,
      `${isSv ? 'Önskat datum / tidsplan' : 'Preferred date / timeline'}: ${formData.eventDate || '-'}`,
      `${isSv ? 'Plats' : 'Location'}: ${formData.location || 'Stockholm'}`,
      `${isSv ? 'Omfattning' : 'Estimated scope'}: ${formData.budget || '-'}`,
      '',
      formData.message,
    ].join('\n')
  );
  const prefilledMailtoHref = `mailto:${STUDIO_CONTACT.email}?subject=${mailtoSubject}&body=${mailtoBody}`;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (status === 'submitting') return;
    setStatus('idle');
    setFieldErrors({});
    setServerMessage('');

    const clientValidation = validateContactPayload({
      ...formData,
      language,
    });

    if (!clientValidation.valid) {
      setFieldErrors(clientValidation.errors);
      const first = Object.keys(clientValidation.errors)[0];
      if (first) {
        document.getElementById(`contact-${first === 'gdprConsent' ? 'gdpr' : first}`)?.focus();
      }
      return;
    }

    const brief = [
      `Company / organisation: ${formData.company}`,
      `Phone: ${formData.phone || 'Not provided'}`,
      `Requested service: ${formData.service}`,
      `Preferred date / timeline: ${formData.eventDate || 'Not specified'}`,
      `Location: ${formData.location || 'Stockholm'}`,
      `Estimated scope: ${formData.budget || 'Not sure yet'}`,
      `Privacy consent: ${formData.gdprConsent ? 'given' : 'not given'}`,
      '',
      formData.message,
    ].join('\n');

    if (brief.length > 2000) {
      setFieldErrors({
        message: isSv
          ? 'Meddelandet är för långt. Förkorta det och försök igen.'
          : 'The enquiry is too long. Please shorten it and try again.',
      });
      document.getElementById('contact-message')?.focus();
      return;
    }

    if (!contactEndpoint) {
      setStatus('email-ready');
      setServerMessage(isSv
        ? 'Förfrågan är inte skickad ännu. Slutför och skicka mejlet i ditt e-postprogram. Om det inte öppnas, använd länken nedan eller kontakta oss direkt.'
        : 'Your enquiry has not been sent yet. Review and send the email in your email app. If it does not open, use the link below or contact us directly.');
      window.location.href = prefilledMailtoHref;
      return;
    }

    setStatus('submitting');

    try {
      const response = await fetch(contactEndpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          ...formData,
          language,
          brief,
          offer: mapServiceToOffer(formData.service),
        }),
      });

      const data = (await response.json().catch(() => ({}))) as {
        accepted?: boolean;
        ok?: boolean;
        message?: string;
        error?: string;
        fieldErrors?: Record<string, string>;
      };

      if (response.ok && (data.accepted === true || data.ok === true)) {
        setStatus('success');
        setServerMessage(data.message || t.contact.formSuccess);
      } else if (data.fieldErrors && typeof data.fieldErrors === 'object' && Object.keys(data.fieldErrors).length > 0) {
        setStatus('idle');
        setFieldErrors(data.fieldErrors);
      } else {
        setStatus('error');
        const isNotConfigured =
          data.error === 'delivery_not_configured' ||
          response.status === 404 ||
          response.status === 405;
        setServerMessage(
          isNotConfigured
            ? isSv
              ? `Förfrågan kunde inte skickas. Öppna det färdigifyllda mejlet nedan och skicka det själv, eller ring ${STUDIO_CONTACT.phone}.`
              : `Your enquiry could not be sent. Open the pre-filled email below and send it from your email app, or call ${STUDIO_CONTACT.phone}.`
            : data.error ||
                (isSv
                  ? `Kunde inte skicka formuläret just nu. Mejla oss direkt på ${STUDIO_CONTACT.email} eller ring ${STUDIO_CONTACT.phone}.`
                  : `Could not send your enquiry right now. Please email us directly at ${STUDIO_CONTACT.email} or call ${STUDIO_CONTACT.phone}.`)
        );

      }
    } catch {
      setStatus('error');
      setServerMessage(
        isSv
          ? `Förfrågan kunde inte skickas. Öppna det färdigifyllda mejlet nedan och skicka det själv, eller ring ${STUDIO_CONTACT.phone}.`
          : `Your enquiry could not be sent. Open the pre-filled email below and send it from your email app, or call ${STUDIO_CONTACT.phone}.`
      );

    }
  };

  return (
    <div
      className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-14 sm:py-24 space-y-12 sm:space-y-20"
    >
      {/* Header (Plain text per Step 3A) */}
      <header className="space-y-6 max-w-4xl">
        <span className="text-xs font-mono uppercase tracking-widest text-[#f59e0b] block">
          DINO STUDIO · STOCKHOLM
        </span>
        <h1 className="font-display text-4xl sm:text-6xl font-black tracking-tight text-white leading-[1.02]">
          {t.contact.pageTitle}
        </h1>
        <p className="text-base sm:text-xl text-[#b0b4be] font-light leading-relaxed max-w-2xl">
          {t.contact.pageSubtitle}
        </p>

        {/* Step 3C: Clear fixed written quote line */}
        <div className="pt-1">
          <div className="inline-flex items-start gap-3 bg-white/[0.04] border border-white/15 rounded-2xl px-5 py-4 text-sm text-white/90">
            <FileText className="w-5 h-5 text-[#f59e0b] shrink-0 mt-0.5" />
            <span>{PRICING_POLICY_NOTE[language]}</span>
          </div>
        </div>

        {/* Mobile Quick-Contact Row (visible above the form on <lg viewports) */}
        <div className="lg:hidden pt-2">
          <div className="flex flex-wrap items-center gap-2.5 text-xs font-mono">
            <a
              href={`mailto:${STUDIO_CONTACT.email}`}
              className="inline-flex items-center gap-2 px-3.5 py-2.5 rounded-xl bg-white/[0.05] border border-white/15 text-white hover:border-[#f59e0b]/60 transition-colors"
            >
              <Mail className="w-3.5 h-3.5 text-[#f59e0b] shrink-0" />
              <span>{STUDIO_CONTACT.email}</span>
            </a>
            <a
              href={STUDIO_CONTACT.phoneHref}
              className="inline-flex items-center gap-2 px-3.5 py-2.5 rounded-xl bg-white/[0.05] border border-white/15 text-white hover:border-[#f59e0b]/60 transition-colors"
            >
              <Phone className="w-3.5 h-3.5 text-[#f59e0b] shrink-0" />
              <span>{STUDIO_CONTACT.phone}</span>
            </a>
            <a
              href={STUDIO_CONTACT.whatsappHref}
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex items-center gap-2 px-3.5 py-2.5 rounded-xl bg-white/[0.05] border border-white/15 text-white hover:border-[#f59e0b]/60 transition-colors"
            >
              <MessageCircle className="w-3.5 h-3.5 text-[#f59e0b] shrink-0" />
              <span>{t.contact.whatsappLabel}</span>
            </a>
          </div>
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-16 items-start">
        {/* Step 3E: Real Server-Validated Contact Form */}
        <div className="lg:col-span-7">
          {status === 'success' ? (
            <div
              role="status"
              aria-live="polite"
              className="p-8 sm:p-10 rounded-3xl bg-emerald-500/10 border border-emerald-500/30 space-y-5"
            >
              <div className="w-12 h-12 bg-emerald-500/20 text-emerald-400 rounded-full flex items-center justify-center">
                <CheckCircle2 className="w-6 h-6" />
              </div>
              <h2 className="font-display text-3xl font-bold text-white">
                {t.contact.formSuccessTitle}
              </h2>
              <p className="text-base text-[#b0b4be] max-w-lg leading-relaxed">
                {serverMessage || t.contact.formSuccess}
              </p>
              <div className="pt-2">
                <button
                  type="button"
                  onClick={() => {
                    setStatus('idle');
                    setServerMessage('');
                  }}
                  className="px-6 py-3 bg-white/10 hover:bg-white/20 text-white rounded-full text-xs font-mono uppercase tracking-wider transition-colors cursor-pointer"
                >
                  {isSv ? 'Skicka en till förfrågan' : 'Send Another Enquiry'}
                </button>
              </div>
            </div>
          ) : (
            <form onSubmit={handleSubmit} noValidate className="space-y-6">
              {/* Server / Delivery Error Banner with Pre-filled Mailto & Direct Phone Fallback */}
              {(status === 'error' || status === 'email-ready') && Object.keys(fieldErrors).length === 0 && (
                <div
                  role={status === 'error' ? 'alert' : 'status'}
                  className="p-5 rounded-2xl bg-amber-500/10 border border-amber-500/40 text-sm text-white space-y-3"
                >
                  <div className="flex items-start gap-3">
                    <AlertCircle className="w-5 h-5 text-[#f59e0b] shrink-0 mt-0.5" />
                    <div className="space-y-3">
                      <p className="font-medium text-white">{serverMessage}</p>
                      <div className="flex flex-wrap items-center gap-3 pt-0.5">
                        <a
                          href={prefilledMailtoHref}
                          className="px-4 py-2.5 rounded-full bg-white text-black hover:bg-neutral-200 font-mono text-xs font-bold uppercase tracking-wider inline-flex items-center gap-2 transition-colors"
                        >
                          <Mail className="w-3.5 h-3.5" />
                          <span>
                            {isSv
                              ? 'Öppna färdigifyllt mejl'
                              : 'Open pre-filled email'}
                          </span>
                        </a>
                      </div>
                      <div className="flex flex-wrap items-center gap-4 pt-1 font-mono text-xs">
                        <a
                          href={`mailto:${STUDIO_CONTACT.email}`}
                          className="text-[#f59e0b] underline hover:text-white flex items-center gap-1.5"
                        >
                          <Mail className="w-3.5 h-3.5" />
                          <span>{STUDIO_CONTACT.email}</span>
                        </a>
                        <a
                          href={STUDIO_CONTACT.phoneHref}
                          className="text-[#f59e0b] underline hover:text-white flex items-center gap-1.5"
                        >
                          <Phone className="w-3.5 h-3.5" />
                          <span>{STUDIO_CONTACT.phone}</span>
                        </a>
                      </div>
                    </div>
                  </div>
                </div>
              )}

              {!contactEndpoint && (
                <p className="text-sm text-[#b0b4be] leading-relaxed">
                  {isSv
                    ? 'Fyll i uppgifterna för att skapa ett färdigifyllt mejl. Du skickar det sedan från ditt eget e-postprogram.'
                    : 'Fill in the details to prepare an email. You then send it from your own email app.'}
                </p>
              )}

              {/* Honeypot field (hidden from real users) */}
              <div className="sr-only" aria-hidden="true">
                <label htmlFor="contact-website-hp">Website</label>
                <input
                  id="contact-website-hp"
                  type="text"
                  name="website"
                  tabIndex={-1}
                  autoComplete="off"
                  value={formData.website}
                  onChange={(e) => setFormData({ ...formData, website: e.target.value })}
                />
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label
                    htmlFor="contact-name"
                    className="block text-xs font-mono uppercase tracking-widest text-white/70"
                  >
                    {t.contact.formName} *
                  </label>
                  <input
                    id="contact-name"
                    aria-invalid={Boolean(fieldErrors.name)}
                    aria-describedby={fieldErrors.name ? 'contact-name-error' : undefined}
                    type="text"
                    required
                    value={formData.name}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    placeholder={isSv ? 'För- och efternamn' : 'First and last name'}
                    className="w-full bg-white/5 border border-white/15 py-3.5 px-4 rounded-xl text-sm text-white placeholder:text-white/30 focus:border-[#f59e0b] focus:outline-hidden"
                  />
                  {fieldErrors.name && (
                    <p id="contact-name-error" className="text-xs font-mono text-amber-400">{fieldErrors.name}</p>
                  )}
                </div>

                <div className="space-y-2">
                  <label
                    htmlFor="contact-company"
                    className="block text-xs font-mono uppercase tracking-widest text-white/70"
                  >
                    {t.contact.formCompany} *
                  </label>
                  <input
                    id="contact-company"
                    aria-invalid={Boolean(fieldErrors.company)}
                    aria-describedby={fieldErrors.company ? 'contact-company-error' : undefined}
                    type="text"
                    required
                    value={formData.company}
                    onChange={(e) => setFormData({ ...formData, company: e.target.value })}
                    placeholder={
                      isSv ? 'Företag, organisation eller klubb' : 'Company, organisation, or club'
                    }
                    className="w-full bg-white/5 border border-white/15 py-3.5 px-4 rounded-xl text-sm text-white placeholder:text-white/30 focus:border-[#f59e0b] focus:outline-hidden"
                  />
                  {fieldErrors.company && (
                    <p id="contact-company-error" className="text-xs font-mono text-amber-400">{fieldErrors.company}</p>
                  )}
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label
                    htmlFor="contact-email"
                    className="block text-xs font-mono uppercase tracking-widest text-white/70"
                  >
                    {t.contact.formEmail} *
                  </label>
                  <input
                    id="contact-email"
                    aria-invalid={Boolean(fieldErrors.email)}
                    aria-describedby={fieldErrors.email ? 'contact-email-error' : undefined}
                    type="email"
                    required
                    value={formData.email}
                    onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                    placeholder="name@organization.se"
                    className="w-full bg-white/5 border border-white/15 py-3.5 px-4 rounded-xl text-sm text-white placeholder:text-white/30 focus:border-[#f59e0b] focus:outline-hidden"
                  />
                  {fieldErrors.email && (
                    <p id="contact-email-error" className="text-xs font-mono text-amber-400">{fieldErrors.email}</p>
                  )}
                </div>

                <div className="space-y-2">
                  <label
                    htmlFor="contact-phone"
                    className="block text-xs font-mono uppercase tracking-widest text-white/70"
                  >
                    {t.contact.formPhone}
                  </label>
                  <input
                    id="contact-phone"
                    aria-invalid={Boolean(fieldErrors.phone)}
                    aria-describedby={fieldErrors.phone ? 'contact-phone-error' : undefined}
                    type="tel"
                    value={formData.phone}
                    onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                    placeholder="+46 70 ..."
                    className="w-full bg-white/5 border border-white/15 py-3.5 px-4 rounded-xl text-sm text-white placeholder:text-white/30 focus:border-[#f59e0b] focus:outline-hidden"
                  />
                  {fieldErrors.phone && (
                    <p id="contact-phone-error" className="text-xs font-mono text-amber-400">{fieldErrors.phone}</p>
                  )}
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label
                    htmlFor="contact-service"
                    className="block text-xs font-mono uppercase tracking-widest text-white/70"
                  >
                    {t.contact.formService} *
                  </label>
                  <select
                    id="contact-service"
                    value={formData.service}
                    onChange={(e) => setFormData({ ...formData, service: e.target.value })}
                    className="w-full bg-white/5 border border-white/15 py-3.5 px-4 rounded-xl text-sm text-white focus:border-[#f59e0b] focus:outline-hidden cursor-pointer"
                  >
                    <option
                      value="Event Photography & Highlight Film"
                      className="bg-[#0c0e13]"
                    >
                      {isSv
                        ? 'Eventfotografering & Highlightfilm'
                        : 'Event Photography & Highlight Film'}
                    </option>
                    <option value="Event Photography" className="bg-[#0c0e13]">
                      {isSv ? 'Eventfotografering' : 'Event Photography'}
                    </option>
                    <option value="Film & Video Production" className="bg-[#0c0e13]">
                      {isSv ? 'Film- & Videoproduktion' : 'Film & Video Production'}
                    </option>
                    <option value="Portrait or Studio Photography" className="bg-[#0c0e13]">
                      {isSv ? 'Porträtt- eller Studiofotografering' : 'Portrait or Studio Photography'}
                    </option>
                    <option value="Product or Brand Photography" className="bg-[#0c0e13]">
                      {isSv ? 'Produkt- eller Varumärkesfotografering' : 'Product or Brand Photography'}
                    </option>
                    <option value="Recurring Content Production" className="bg-[#0c0e13]">
                      {isSv
                        ? 'Löpande Foto- & Filmproduktion'
                        : 'Recurring Photography & Film Production'}
                    </option>
                    <option value="Digital, Web, Graphic Design or Logo Animation" className="bg-[#0c0e13]">
                      {isSv
                        ? 'Digitalt, Webb, Grafisk design eller Logotypanimation'
                        : 'Digital, Web, Graphic Design or Logo Animation'}
                    </option>
                    <option value="Other / Combined Assignment" className="bg-[#0c0e13]">
                      {isSv ? 'Annat / Kombinerat uppdrag' : 'Other / Combined Assignment'}
                    </option>
                  </select>
                </div>

                <div className="space-y-2">
                  <label
                    htmlFor="contact-date"
                    className="block text-xs font-mono uppercase tracking-widest text-white/70"
                  >
                    {t.contact.formDate}
                  </label>
                  <input
                    id="contact-date"
                    type="text"
                    value={formData.eventDate}
                    onChange={(e) => setFormData({ ...formData, eventDate: e.target.value })}
                    placeholder={
                      isSv ? 't.ex. datum eller önskad månad' : 'e.g. specific date or target month'
                    }
                    className="w-full bg-white/5 border border-white/15 py-3.5 px-4 rounded-xl text-sm text-white placeholder:text-white/30 focus:border-[#f59e0b] focus:outline-hidden"
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label
                    htmlFor="contact-location"
                    className="block text-xs font-mono uppercase tracking-widest text-white/70"
                  >
                    {t.contact.formLocation}
                  </label>
                  <input
                    id="contact-location"
                    type="text"
                    value={formData.location}
                    onChange={(e) => setFormData({ ...formData, location: e.target.value })}
                    placeholder={isSv ? 'Stockholm / Annan ort' : 'Stockholm / Other location'}
                    className="w-full bg-white/5 border border-white/15 py-3.5 px-4 rounded-xl text-sm text-white placeholder:text-white/30 focus:border-[#f59e0b] focus:outline-hidden"
                  />
                </div>

                <div className="space-y-2">
                  <label
                    htmlFor="contact-budget"
                    className="block text-xs font-mono uppercase tracking-widest text-white/70"
                  >
                    {t.contact.formBudget}
                  </label>
                  <select
                    id="contact-budget"
                    value={formData.budget}
                    onChange={(e) => setFormData({ ...formData, budget: e.target.value })}
                    className="w-full bg-white/5 border border-white/15 py-3.5 px-4 rounded-xl text-sm text-white focus:border-[#f59e0b] focus:outline-hidden cursor-pointer"
                  >
                    <option value="not-sure" className="bg-[#0c0e13]">
                      {isSv ? 'Vet ej ännu — önskar skriftlig offert' : 'Not sure yet — request written quote'}
                    </option>
                    <option value="short-session" className="bg-[#0c0e13]">
                      {isSv ? 'Kortare uppdrag / Porträtt (1–2 timmar)' : 'Short session / Portrait (1–2 hours)'}
                    </option>
                    <option value="half-day" className="bg-[#0c0e13]">
                      {isSv ? 'Halvdag (Event, foto eller produkt)' : 'Half-day (Event, photo, or product)'}
                    </option>
                    <option value="full-day" className="bg-[#0c0e13]">
                      {isSv
                        ? 'Heldag (Foto och/eller film)'
                        : 'Full-day (Photography and/or film)'}
                    </option>
                    <option value="multi-day-or-ongoing" className="bg-[#0c0e13]">
                      {isSv
                        ? 'Flera dagar, löpande produktion eller digitalt projekt'
                        : 'Multi-day, ongoing production, or digital project'}
                    </option>
                  </select>
                </div>
              </div>

              <div className="space-y-2">
                <label
                  htmlFor="contact-message"
                  className="block text-xs font-mono uppercase tracking-widest text-white/70"
                >
                  {t.contact.formMessage} *
                </label>
                <textarea
                  id="contact-message"
                    aria-invalid={Boolean(fieldErrors.message)}
                    aria-describedby={fieldErrors.message ? 'contact-message-error' : undefined}
                  rows={5}
                  required
                  value={formData.message}
                  onChange={(e) => setFormData({ ...formData, message: e.target.value })}
                  placeholder={
                    isSv
                      ? 'Beskriv kort vad ni vill producera (event, porträtt, produktfoto, film eller webb/design), ungefärlig omfattning och önskade leveranser...'
                      : 'Briefly describe what you need produced (event, portrait, product photography, film, or web/design), approximate scope, and desired deliverables...'
                  }
                  className="w-full bg-white/5 border border-white/15 p-4 rounded-xl text-sm text-white placeholder:text-white/30 focus:border-[#f59e0b] focus:outline-hidden resize-none"
                />
                {fieldErrors.message && (
                  <p id="contact-message-error" className="text-xs font-mono text-amber-400">{fieldErrors.message}</p>
                )}
              </div>

              {/* Required GDPR Consent Checkbox */}
              <div className="space-y-2 pt-1">
                <label className="flex items-start gap-3 cursor-pointer text-xs sm:text-sm text-[#b0b4be]">
                  <input
                    id="contact-gdpr"
                    required
                    aria-invalid={Boolean(fieldErrors.gdprConsent)}
                    aria-describedby={fieldErrors.gdprConsent ? 'contact-gdpr-error' : undefined}
                    type="checkbox"
                    checked={formData.gdprConsent}
                    onChange={(e) =>
                      setFormData({ ...formData, gdprConsent: e.target.checked })
                    }
                    className="mt-1 w-4 h-4 accent-[#f59e0b] rounded cursor-pointer shrink-0"
                  />
                  <span>
                    {t.contact.formGdprLabel}{' '}
                    {onNavigate ? (
                      <button
                        type="button"
                        onClick={() => onNavigate('privacy')}
                        className="text-white underline hover:text-[#f59e0b] cursor-pointer"
                      >
                        {t.contact.formPrivacyLink}
                      </button>
                    ) : (
                      <a href={`/${language}/privacy/`} className="text-white underline hover:text-[#f59e0b]">
                        {t.contact.formPrivacyLink}
                      </a>
                    )}
                    . *
                  </span>
                </label>
                {fieldErrors.gdprConsent && (
                  <p id="contact-gdpr-error" className="text-xs font-mono text-amber-400">{fieldErrors.gdprConsent}</p>
                )}
              </div>

              <div className="pt-2">
                <button
                  type="submit"
                  disabled={status === 'submitting'}
                  className="px-8 py-4 bg-white text-black hover:bg-neutral-200 disabled:opacity-50 rounded-full font-mono text-xs font-bold uppercase tracking-widest transition-colors cursor-pointer flex items-center gap-2.5"
                >
                  <Send className="w-4 h-4" />
                  <span>
                    {status === 'submitting' ? t.contact.formSubmitting : contactEndpoint ? t.contact.formSubmit : isSv ? 'Öppna färdigifyllt mejl' : 'Open pre-filled email'}
                  </span>
                </button>
              </div>
            </form>
          )}
        </div>

        {/* Direct Contact Column */}
        <div className="lg:col-span-5 space-y-8 lg:pl-8 border-t lg:border-t-0 lg:border-l border-white/10 pt-8 lg:pt-0">
          <div className="space-y-2">
            <span className="text-xs font-mono uppercase tracking-widest text-[#f59e0b] block">
              {t.contact.directContactTitle}
            </span>
            <h2 className="font-display text-2xl font-bold text-white">
              Dino Studio
            </h2>
            <p className="text-sm text-[#b0b4be]">
              {t.contact.workingHours}
            </p>
          </div>

          <div className="space-y-4 text-sm font-mono text-white/85">
            <a
              href={`mailto:${STUDIO_CONTACT.email}`}
              className="flex items-center gap-3 p-3.5 rounded-2xl bg-white/[0.04] border border-white/10 hover:border-[#f59e0b]/60 hover:text-[#f59e0b] transition-colors"
            >
              <Mail className="w-4 h-4 text-[#f59e0b] shrink-0" />
              <div className="flex flex-col">
                <span className="text-[11px] uppercase tracking-widest text-white/65">
                  {t.contact.emailLabel}
                </span>
                <span className="text-white">{STUDIO_CONTACT.email}</span>
              </div>
            </a>
            <a
              href={STUDIO_CONTACT.phoneHref}
              className="flex items-center gap-3 p-3.5 rounded-2xl bg-white/[0.04] border border-white/10 hover:border-[#f59e0b]/60 hover:text-[#f59e0b] transition-colors"
            >
              <Phone className="w-4 h-4 text-[#f59e0b] shrink-0" />
              <div className="flex flex-col">
                <span className="text-[11px] uppercase tracking-widest text-white/65">
                  {t.contact.callLabel}
                </span>
                <span className="text-white">{STUDIO_CONTACT.phone}</span>
              </div>
            </a>
            <a
              href={STUDIO_CONTACT.whatsappHref}
              target="_blank"
              rel="noopener noreferrer"
              className="flex items-center gap-3 p-3.5 rounded-2xl bg-white/[0.04] border border-white/10 hover:border-[#f59e0b]/60 hover:text-[#f59e0b] transition-colors"
            >
              <MessageCircle className="w-4 h-4 text-[#f59e0b] shrink-0" />
              <div className="flex flex-col">
                <span className="text-[11px] uppercase tracking-widest text-white/65">
                  {t.contact.whatsappLabel}
                </span>
                <span className="text-white">{STUDIO_CONTACT.phone}</span>
              </div>
            </a>
            <div className="flex items-center gap-3 text-white/60 pt-2">
              <MapPin className="w-4 h-4 text-[#f59e0b]" />
              <span>{isSv ? STUDIO_CONTACT.locationSv : STUDIO_CONTACT.locationEn}</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};
