export interface ContactFormPayload {
  name: string;
  company: string;
  email: string;
  phone?: string;
  service: string;
  eventDate?: string;
  location?: string;
  budget?: string;
  message: string;
  gdprConsent: boolean;
  website?: string; // Honeypot field — must remain empty
  language?: 'en' | 'sv';
}

export interface ValidationResult {
  valid: boolean;
  honeypotTriggered?: boolean;
  errors: Record<string, string>;
  sanitized?: {
    name: string;
    company: string;
    email: string;
    phone: string;
    service: string;
    eventDate: string;
    location: string;
    budget: string;
    message: string;
    gdprConsent: boolean;
    language: 'en' | 'sv';
  };
}

const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export function validateContactPayload(input: Partial<ContactFormPayload> | null | undefined): ValidationResult {
  const errors: Record<string, string> = {};

  if (!input || typeof input !== 'object') {
    return {
      valid: false,
      errors: { form: 'Invalid request payload.' },
    };
  }

  // Honeypot check: if a bot fills the hidden website field, flag immediately
  const honeypot = typeof input.website === 'string' ? input.website.trim() : '';
  if (honeypot.length > 0) {
    return {
      valid: false,
      honeypotTriggered: true,
      errors: { website: 'Spam detected.' },
    };
  }

  const name = typeof input.name === 'string' ? input.name.trim() : '';
  const company = typeof input.company === 'string' ? input.company.trim() : '';
  const email = typeof input.email === 'string' ? input.email.trim() : '';
  const phone = typeof input.phone === 'string' ? input.phone.trim() : '';
  const service = typeof input.service === 'string' ? input.service.trim() : '';
  const eventDate = typeof input.eventDate === 'string' ? input.eventDate.trim() : '';
  const location = typeof input.location === 'string' ? input.location.trim() : '';
  const budget = typeof input.budget === 'string' ? input.budget.trim() : '';
  const message = typeof input.message === 'string' ? input.message.trim() : '';
  const gdprConsent = input.gdprConsent === true;
  const language: 'en' | 'sv' = input.language === 'sv' ? 'sv' : 'en';

  if (name.length < 2 || name.length > 120) {
    errors.name = language === 'sv' ? 'Ange ditt namn (minst 2 tecken).' : 'Please enter your name (at least 2 characters).';
  }

  if (company.length < 2 || company.length > 150) {
    errors.company =
      language === 'sv'
        ? 'Ange företag, organisation eller förening.'
        : 'Please enter your company, organisation, or club.';
  }

  if (!email || !EMAIL_REGEX.test(email) || email.length > 180) {
    errors.email =
      language === 'sv' ? 'Ange en giltig e-postadress.' : 'Please enter a valid email address.';
  }

  if (phone.length > 40) {
    errors.phone = language === 'sv' ? 'Telefonnumret är för långt.' : 'Phone number is too long.';
  }

  if (!service || service.length > 100) {
    errors.service = language === 'sv' ? 'Välj en tjänst.' : 'Please select a service.';
  }

  if (message.length < 10 || message.length > 4000) {
    errors.message =
      language === 'sv'
        ? 'Beskriv ert event eller projekt (minst 10 tecken).'
        : 'Please describe your event or project (at least 10 characters).';
  }

  if (!gdprConsent) {
    errors.gdprConsent =
      language === 'sv'
        ? 'Du behöver godkänna att vi behandlar dina uppgifter för att besvara förfrågan.'
        : 'Please confirm consent so we can process your enquiry.';
  }

  if (Object.keys(errors).length > 0) {
    return { valid: false, errors };
  }

  return {
    valid: true,
    errors: {},
    sanitized: {
      name,
      company,
      email,
      phone,
      service,
      eventDate: eventDate || (language === 'sv' ? 'Ej angivet' : 'Not specified'),
      location: location || 'Stockholm',
      budget: budget || (language === 'sv' ? 'Vet ej ännu' : 'Not sure yet'),
      message,
      gdprConsent,
      language,
    },
  };
}

export function formatEnquiryEmailText(data: NonNullable<ValidationResult['sanitized']>): {
  subject: string;
  text: string;
} {
  const subject = `[Dino Studio Enquiry] ${data.company} — ${data.service}`;
  const text = [
    `New project enquiry via dinostudio.se`,
    `--------------------------------------------------`,
    `Name:          ${data.name}`,
    `Company/Org:   ${data.company}`,
    `Email:         ${data.email}`,
    `Phone:         ${data.phone || 'Not provided'}`,
    `Service:       ${data.service}`,
    `Event Date:    ${data.eventDate}`,
    `Location:      ${data.location}`,
    `Budget Range:  ${data.budget}`,
    `GDPR Consent:  Yes (${new Date().toISOString()})`,
    `--------------------------------------------------`,
    ``,
    `Project Brief / Message:`,
    data.message,
  ].join('\n');

  return { subject, text };
}

export interface RateLimiter {
  check(ip: string, nowMs?: number): { allowed: boolean; retryAfterSeconds: number };
}

export function createRateLimiter(maxRequests = 5, windowMs = 15 * 60 * 1000): RateLimiter {
  const store = new Map<string, number[]>();

  return {
    check(ip: string, nowMs: number = Date.now()) {
      const key = ip || 'unknown';
      const existing = store.get(key) || [];
      const recent = existing.filter((ts) => nowMs - ts < windowMs);

      if (recent.length >= maxRequests) {
        const oldest = recent[0];
        const retryAfterSeconds = Math.max(1, Math.ceil((windowMs - (nowMs - oldest)) / 1000));
        store.set(key, recent);
        return { allowed: false, retryAfterSeconds };
      }

      recent.push(nowMs);
      store.set(key, recent);
      return { allowed: true, retryAfterSeconds: 0 };
    },
  };
}

export interface ContactEnvConfig {
  CONTACT_TO_EMAIL?: string;
  CONTACT_FROM_EMAIL?: string;
  RESEND_API_KEY?: string;
  EMAIL_WEBHOOK_URL?: string;
  EMAIL_WEBHOOK_TOKEN?: string;
}

export async function deliverContactEnquiry(
  payload: {
    replyTo: string;
    subject: string;
    text: string;
    raw: Record<string, unknown>;
  },
  env: ContactEnvConfig = process.env as ContactEnvConfig,
  fetchImpl: typeof fetch = fetch
): Promise<{ delivered: boolean; error?: string }> {
  const toEmail = (env.CONTACT_TO_EMAIL || '').trim() || 'info@dinostudio.se';
  const fromEmail =
    (env.CONTACT_FROM_EMAIL || '').trim() || 'Dino Studio Website <no-reply@dinostudio.se>';
  const resendApiKey = (env.RESEND_API_KEY || '').trim();
  const webhookUrl = (env.EMAIL_WEBHOOK_URL || '').trim();
  const webhookToken = (env.EMAIL_WEBHOOK_TOKEN || '').trim();

  // Option A: Resend HTTP API (alternative 1)
  if (resendApiKey) {
    try {
      const response = await fetchImpl('https://api.resend.com/emails', {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${resendApiKey}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          from: fromEmail,
          to: [toEmail],
          reply_to: payload.replyTo,
          subject: payload.subject,
          text: payload.text,
        }),
      });

      if (!response.ok) {
        return {
          delivered: false,
          error: 'PROVIDER_REJECTED',
        };
      }
      return { delivered: true };
    } catch {
      return {
        delivered: false,
        error: 'PROVIDER_UNREACHABLE',
      };
    }
  }

  // Option B: Custom SMTP/Email Webhook relay (alternative 2)
  if (webhookUrl) {
    try {
      const headers: Record<string, string> = {
        'Content-Type': 'application/json',
      };
      if (webhookToken) {
        headers.Authorization = `Bearer ${webhookToken}`;
      }
      const response = await fetchImpl(webhookUrl, {
        method: 'POST',
        headers,
        body: JSON.stringify({
          to: toEmail,
          from: fromEmail,
          replyTo: payload.replyTo,
          subject: payload.subject,
          text: payload.text,
          enquiry: payload.raw,
        }),
      });

      if (!response.ok) {
        return {
          delivered: false,
          error: 'WEBHOOK_REJECTED',
        };
      }
      return { delivered: true };
    } catch {
      return {
        delivered: false,
        error: 'WEBHOOK_UNREACHABLE',
      };
    }
  }

  // Neither RESEND_API_KEY nor EMAIL_WEBHOOK_URL is configured
  return {
    delivered: false,
    error: 'EMAIL_TRANSPORT_UNCONFIGURED',
  };
}

