/** The static host has no API. A public endpoint must be explicitly configured. */
export function resolveContactEndpoint(configured: string | undefined, development = false): string | null {
  const endpoint = configured?.trim();
  if (!endpoint) return development ? '/api/contact' : null;
  if (endpoint === '/api/contact') return endpoint;
  const url = new URL(endpoint);
  if (url.protocol !== 'https:' || url.username || url.password || url.hash) {
    throw new Error('Contact endpoint must be an HTTPS URL without credentials or a fragment.');
  }
  return url.href;
}
